import fs from "node:fs";
import path from "node:path";

function must(condition, message) {
  if (!condition) throw new Error(message);
}

function write(file, content) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content, "utf8");
}

function replaceOnce(source, before, after, label) {
  const index = source.indexOf(before);
  must(index >= 0, `Missing anchor: ${label}`);
  must(source.indexOf(before, index + before.length) < 0, `Duplicate anchor: ${label}`);
  return source.slice(0, index) + after + source.slice(index + before.length);
}

write("src/games/entertainment.js", "const TRUTH_QUESTIONS = Object.freeze([\n  \"最近一次让你真心开心的事情是什么？\",\n  \"你最想改掉自己的哪个小习惯？\",\n  \"你做过最冲动但不后悔的决定是什么？\",\n  \"群里谁最可能在半夜突然发消息？\",\n  \"你最怕别人误会你的哪一点？\",\n  \"你最想重新体验哪一天？\",\n  \"你最常用来拖延的理由是什么？\",\n  \"你最佩服身边谁的哪种能力？\",\n  \"你最近偷偷期待的事情是什么？\",\n  \"你最不擅长拒绝哪类请求？\",\n  \"你曾经为了面子做过什么傻事？\",\n  \"你最希望别人记住你的什么特点？\",\n  \"你最想学会但一直没开始的技能是什么？\",\n  \"你最容易在哪种情况下心软？\",\n  \"你最近一次道歉是因为什么？\",\n  \"你最想对过去的自己说什么？\",\n  \"哪首歌最像你最近的心情？\",\n  \"你觉得自己最可靠的优点是什么？\",\n  \"你最想和群里的谁交换一天生活？\",\n  \"你最近发现自己有什么变化？\"\n]);\n\nconst DARE_TASKS = Object.freeze([\n  \"用一句话认真夸群里一位成员。\",\n  \"把昵称临时改成一个食物名十分钟。\",\n  \"发一句不带任何表情的冷笑话。\",\n  \"用三句话推荐一部你喜欢的作品。\",\n  \"连续发三个不同的拟声词。\",\n  \"用一句古风台词介绍自己。\",\n  \"分享一个今天学到的小知识。\",\n  \"用不超过十五个字描述你现在的心情。\",\n  \"给群里最近一位发言者取一个友善称号。\",\n  \"用播音腔读出一句普通日常话。\",\n  \"只用疑问句回复下一位和你说话的人一次。\",\n  \"说出三种你喜欢的食物。\",\n  \"用一句话给明天的自己打气。\",\n  \"发一条没有标点符号的祝福。\",\n  \"用五个字概括你今天。\",\n  \"模仿天气预报介绍自己的状态。\",\n  \"给群里出一道简单脑筋急转弯。\",\n  \"用一句广告词推荐你现在最想吃的东西。\",\n  \"分享一个无伤害的小失败经历。\",\n  \"用一句话感谢最近帮助过你的人。\"\n]);\n\nconst FORTUNE_LEVELS = Object.freeze([\n  { max: 20, label: \"小凶\", advice: \"今天适合放慢节奏，重要决定多确认一次。\" },\n  { max: 40, label: \"末吉\", advice: \"保持耐心，先完成手边最小的一件事。\" },\n  { max: 60, label: \"中吉\", advice: \"状态平稳，按计划推进会有不错结果。\" },\n  { max: 80, label: \"吉\", advice: \"适合主动沟通，也可以尝试一点新东西。\" },\n  { max: 100, label: \"大吉\", advice: \"行动力很强，记得把好运分给身边的人。\" }\n]);\n\nfunction clampRandom(random) {\n  const value = Number(typeof random === \"function\" ? random() : Math.random());\n  if (!Number.isFinite(value)) return 0;\n  return Math.min(0.999999999999, Math.max(0, value));\n}\n\nfunction randomInt(min, max, random = Math.random) {\n  return Math.floor(clampRandom(random) * (max - min + 1)) + min;\n}\n\nfunction pick(items, random = Math.random) {\n  return items[randomInt(0, items.length - 1, random)];\n}\n\nfunction normalizeCommandText(value) {\n  return String(value || \"\").normalize(\"NFKC\").trim();\n}\n\nfunction stripCommandPrefix(value) {\n  return normalizeCommandText(value).replace(/^[!！]+/, \"\").trim();\n}\n\nfunction stableHash(value) {\n  let hash = 2166136261;\n  for (const char of String(value || \"\")) {\n    hash ^= char.codePointAt(0);\n    hash = Math.imul(hash, 16777619);\n  }\n  return hash >>> 0;\n}\n\nfunction taipeiDateKey(now = Date.now()) {\n  const date = new Date(Number(now) || Date.now());\n  return new Intl.DateTimeFormat(\"en-CA\", {\n    timeZone: \"Asia/Taipei\",\n    year: \"numeric\",\n    month: \"2-digit\",\n    day: \"2-digit\"\n  }).format(date);\n}\n\nfunction parseDice(body) {\n  const match = body.match(/^(?:骰子|掷骰子|擲骰子|roll)(?:\\s+(\\d{1,2})(?:\\s*[dD]\\s*(\\d{1,4}))?)?$/i);\n  if (!match) return null;\n  const count = Number(match[1] || 1);\n  const sides = Number(match[2] || 6);\n  if (!Number.isInteger(count) || count < 1 || count > 20) {\n    return { error: \"骰子数量需为 1～20。格式：!骰子 3d20\" };\n  }\n  if (!Number.isInteger(sides) || sides < 2 || sides > 1000) {\n    return { error: \"骰子面数需为 2～1000。格式：!骰子 3d20\" };\n  }\n  return { count, sides };\n}\n\nfunction parseRandomRange(body) {\n  const match = body.match(/^(?:随机数|隨機數|随机|隨機|rand)(?:\\s+(-?\\d+)(?:\\s*(?:到|至|[-~～,，\\s])\\s*(-?\\d+))?)?$/i);\n  if (!match) return null;\n  if (match[1] == null) return { min: 1, max: 100 };\n  const first = Number(match[1]);\n  const second = match[2] == null ? 1 : Number(match[2]);\n  const min = Math.min(first, second);\n  const max = Math.max(first, second);\n  if (!Number.isSafeInteger(min) || !Number.isSafeInteger(max)) {\n    return { error: \"随机数范围必须是安全整数。\" };\n  }\n  if (max - min > 1_000_000_000) {\n    return { error: \"随机数范围不能超过十亿。\" };\n  }\n  return { min, max };\n}\n\nfunction splitChoices(raw) {\n  return String(raw || \"\")\n    .split(/\\s*(?:\\||｜|、|,|，|\\/)\\s*/)\n    .map(item => item.trim())\n    .filter(Boolean);\n}\n\nfunction handleEntertainmentCommand({\n  text,\n  userId = \"\",\n  groupId = \"\",\n  now = Date.now(),\n  random = Math.random\n} = {}) {\n  const normalized = normalizeCommandText(text);\n  if (!/^[!！]/.test(normalized)) return { handled: false };\n  const body = stripCommandPrefix(normalized);\n\n  const dice = parseDice(body);\n  if (dice) {\n    if (dice.error) return { handled: true, command: \"dice\", text: dice.error };\n    const values = Array.from({ length: dice.count }, () => randomInt(1, dice.sides, random));\n    const total = values.reduce((sum, value) => sum + value, 0);\n    const detail = values.join(\"、\");\n    return {\n      handled: true,\n      command: \"dice\",\n      text: dice.count === 1\n        ? `骰子结果：${detail}`\n        : `骰子结果：${detail}\\n总点数：${total}`\n    };\n  }\n\n  const range = parseRandomRange(body);\n  if (range) {\n    if (range.error) return { handled: true, command: \"random\", text: range.error };\n    return {\n      handled: true,\n      command: \"random\",\n      text: `随机结果：${randomInt(range.min, range.max, random)}（范围 ${range.min}～${range.max}）`\n    };\n  }\n\n  if (/^(?:硬币|硬幣|抛硬币|拋硬幣|丢硬币|丟硬幣|coin)$/i.test(body)) {\n    return {\n      handled: true,\n      command: \"coin\",\n      text: `硬币结果：${pick([\"正面\", \"反面\"], random)}`\n    };\n  }\n\n  const rps = body.match(/^(?:猜拳|石头剪刀布|石頭剪刀布|rps)(?:\\s+(石头|石頭|剪刀|布))?$/i);\n  if (rps) {\n    if (!rps[1]) {\n      return { handled: true, command: \"rps\", text: \"格式：!猜拳 石头／剪刀／布\" };\n    }\n    const user = rps[1].replace(\"石頭\", \"石头\");\n    const bot = pick([\"石头\", \"剪刀\", \"布\"], random);\n    const result = user === bot\n      ? \"平局\"\n      : (user === \"石头\" && bot === \"剪刀\") || (user === \"剪刀\" && bot === \"布\") || (user === \"布\" && bot === \"石头\")\n        ? \"你赢了\"\n        : \"你输了\";\n    return { handled: true, command: \"rps\", text: `你出${user}，我出${bot}：${result}。` };\n  }\n\n  const choice = body.match(/^(?:选择|選擇|选一个|選一個|帮我选|幫我選)(?:\\s+([\\s\\S]+))?$/i);\n  if (choice) {\n    const options = splitChoices(choice[1] || \"\");\n    if (options.length < 2) {\n      return { handled: true, command: \"choice\", text: \"至少提供两个选项，用“|”分隔。例如：!选择 火锅 | 烧烤\" };\n    }\n    if (options.length > 20 || options.some(item => item.length > 60) || options.join(\"\").length > 500) {\n      return { handled: true, command: \"choice\", text: \"最多 20 个选项，每项不超过 60 字。\" };\n    }\n    return { handled: true, command: \"choice\", text: `我选：${pick(options, random)}` };\n  }\n\n  if (/^(?:今日运势|今日運勢|今天运势|今天運勢|运势|運勢)$/i.test(body)) {\n    const dateKey = taipeiDateKey(now);\n    const score = stableHash(`${dateKey}:${groupId}:${userId}`) % 100 + 1;\n    const level = FORTUNE_LEVELS.find(item => score <= item.max) || FORTUNE_LEVELS.at(-1);\n    const luckyNumber = stableHash(`number:${dateKey}:${userId}`) % 9 + 1;\n    return {\n      handled: true,\n      command: \"fortune\",\n      text: `今日运势：${level.label}（${score}/100）\\n幸运数字：${luckyNumber}\\n建议：${level.advice}`\n    };\n  }\n\n  if (/^(?:真心话|真心話|truth)$/i.test(body)) {\n    return { handled: true, command: \"truth\", text: `真心话：${pick(TRUTH_QUESTIONS, random)}` };\n  }\n\n  if (/^(?:大冒险|大冒險|dare)$/i.test(body)) {\n    return { handled: true, command: \"dare\", text: `大冒险：${pick(DARE_TASKS, random)}` };\n  }\n\n  return { handled: false };\n}\n\nexport {\n  DARE_TASKS,\n  TRUTH_QUESTIONS,\n  handleEntertainmentCommand,\n  parseDice,\n  parseRandomRange,\n  splitChoices,\n  stableHash,\n  taipeiDateKey\n};\n");
write("src/help/commands.js", "function section(title, entries) {\n  if (!entries.length) return \"\";\n  return [`【${title}】`, ...entries.map(entry => `• ${entry}`)].join(\"\\n\");\n}\n\nfunction roleLabel({ isDeveloper, role, aiAdmin, groupOps }) {\n  if (isDeveloper) return \"开发者\";\n  if (role === \"owner\") return \"群主\";\n  if (role === \"admin\") return \"QQ 管理员\";\n  if (aiAdmin && groupOps) return \"AI 管理＋群操作\";\n  if (groupOps) return \"群操作权限\";\n  if (aiAdmin) return \"AI 管理权限\";\n  return \"群成员\";\n}\n\nfunction buildCommandHelp({\n  role = \"member\",\n  isDeveloper = false,\n  aiAdmin = false,\n  groupOps = false\n} = {}) {\n  const parts = [\n    `QQAI 指令帮助`,\n    `当前权限：${roleLabel({ isDeveloper, role, aiAdmin, groupOps })}`,\n    `Control Center：https://qqai.ray2025.com/`,\n    \"\",\n    section(\"基础与多模态\", [\n      \"`!help`：查看当前权限可用指令\",\n      \"`!status`／`!配额`：查看模型、记忆与运行状态\",\n      \"`!live`：取得即时语音页面\",\n      \"`!语音 <问题>`：生成语音回答\",\n      \"`!读网页 <网址>`：读取并摘要网页\",\n      \"`!翻译 <语言> <内容>`：翻译文字\",\n      \"图片理解：发送图片和问题，或回复图片后 @机器人\"\n    ]),\n    \"\",\n    section(\"娱乐小游戏（不消耗模型 API）\", [\n      \"`!骰子 [数量]d[面数]`：例如 `!骰子 3d20`\",\n      \"`!随机数 [最小值] [最大值]`：默认 1～100\",\n      \"`!硬币`：随机正面或反面\",\n      \"`!猜拳 石头／剪刀／布`：和机器人猜拳\",\n      \"`!选择 选项A | 选项B`：随机选择一个选项\",\n      \"`!今日运势`：同一用户同一天结果固定\",\n      \"`!真心话`：抽取安全问题\",\n      \"`!大冒险`：抽取无伤害任务\"\n    ]),\n    \"\",\n    section(\"分析与资料\", [\n      \"`!会议纪要 [条数]`：整理近期群聊重点\",\n      \"`!总结 [条数]`／`!吃瓜`：轻松总结近期聊天\",\n      \"`!查成分 [@成员]`：分析公开聊天特征\",\n      \"`!详细资料 [@成员]`：本人查自己；查他人需对应权限\"\n    ]),\n    \"\",\n    section(\"个人、记忆与群规\", [\n      \"`!群规`／`!rules`：查看群规\",\n      \"`!免打扰`／`!取消免打扰`：控制主动互动\",\n      \"`!好感度 [@成员]`：查看当前关系评估\",\n      \"`!检查 <具体原因>`：回复目标消息进行人工补检\",\n      \"`!记住 [@成员] <内容>`：写入允许的个人记忆\",\n      \"`!忘记 [@成员] <内容>`：删除匹配记忆\",\n      \"`!你记住了什么 [@成员]`：查看可见记忆\",\n      \"`!set人格 <风格>`／`!del人格`：管理个人外挂机格\",\n      \"`!协助撤回`：回复自己的消息后撤回\"\n    ]),\n    \"\",\n    section(\"活动、投票、排程与申诉\", [\n      \"`!活动`：查看或建立活动（高风险步骤会二次确认）\",\n      \"`!报名 <活动>`／`!取消报名 <活动>`：报名或取消\",\n      \"`!投票`：查看投票帮助\",\n      \"`!投票 选择 <编号> <选项>`：参与投票\",\n      \"`!排程 2026-07-28 18:00 <内容>`：建立一次排程\",\n      \"`!排程 每天 18:00 <内容>`：建立重复排程\",\n      \"`!排程 列表`／`!排程 取消 <编号>`：管理自己的排程\",\n      \"私聊 `!申诉 <群号> <类型> <详细内容>`：提交申诉\"\n    ])\n  ];\n\n  if (aiAdmin) {\n    parts.push(\n      \"\",\n      section(\"AI 管理\", [\n        \"`!关闭ai`／`!开启ai`：切换本群 AI 回复\",\n        \"`!记忆开`／`!记忆关`：切换长期记忆\",\n        \"`!拉黑 @成员`／`!洗白 @成员`：控制 AI 是否回应\",\n        \"`!set群规 <内容>`：设置群规\",\n        \"`!群规监控 开／关／状态`：控制持续检查\",\n        \"`!群规严格度 智慧／宽松／低／中／高／严格`：调整判定\",\n        \"`!违规禁言保护 开／关／状态`：控制禁言保护\",\n        \"`!切换人格 <风格>`／`!恢复人格`：管理群组人格\",\n        \"`!设置插话率 0-100`：调整主动插话率\",\n        \"`!好感度注入 开／关／状态`：控制好感度上下文\",\n        \"`!清空群上下文`：清空短期上下文与摘要\"\n      ])\n    );\n  }\n\n  if (groupOps) {\n    parts.push(\n      \"\",\n      section(\"群操作\", [\n        \"`!禁言 @成员 <时长>`／`!解禁 @成员`\",\n        \"`!撤回`：管理员回复目标消息\",\n        \"`!踢出 @成员`\",\n        \"`!全员禁言`／`!解除全员禁言`\",\n        \"`!改群名 <新名称>`\",\n        \"`!改名片 @成员 <新名片>`\",\n        \"`确认op`／`取消op`：确认或取消高风险操作\"\n      ])\n    );\n  }\n\n  if (role === \"owner\" || isDeveloper) {\n    parts.push(\n      \"\",\n      section(\"群主与开发者设置\", [\n        \"`!群白名单 <群号>`／`!删群白名单 <群号>`\",\n        \"`!取消使用`：停止全局模仿或人格覆盖\"\n      ])\n    );\n  }\n\n  if (isDeveloper) {\n    parts.push(\n      \"\",\n      section(\"开发者专属\", [\n        \"`!授权 @成员 <权限类型>`／`!撤销授权 @成员 <权限类型>`\",\n        \"`!禁记忆 @成员`／`!解禁记忆 @成员`\",\n        \"`!自我调整`／`!自我修正`\",\n        \"`!重置`／`!clear`：清空当前群临时状态\"\n      ])\n    );\n  }\n\n  parts.push(\n    \"\",\n    section(\"触发说明\", [\n      \"群友发送 `/!普通聊天内容`：完全跳过聊天、群规与插话 AI\",\n      \"机器人同号人工聊天：使用 `//内容`、`??内容` 或 `/!内容`\",\n      \"机器人同号人工指令：直接使用 `!指令`\",\n      \"政治相关普通聊天会静默忽略\"\n    ])\n  );\n\n  return parts.filter((part, index, array) => !(part === \"\" && array[index - 1] === \"\")).join(\"\\n\").trim();\n}\n\nexport { buildCommandHelp, roleLabel };\n");
write("README.md", "# QQ AI Bot（qqaibot）\n\n目前版本：**2.7.11**\n\n這是一個部署於 Cloudflare Workers 的 QQ／OneBot 群聊機器人。專案維持「單一 Worker 對外服務、原始碼依職責模組化」的架構：Cloudflare 實際入口仍為根目錄 `worker.js`，AI、Portal、群管、排程、遊戲、通知與資料存取邏輯則放在 `src/`。\n\n> 本專案透過第三方 QQ／OneBot 客戶端連接 QQ，可能涉及平台條款、帳號限制與封禁風險。請使用專用測試帳號，並自行承擔部署與執行風險。\n\n## 現行架構\n\n- **Cloudflare Worker**：唯一對外入口 `worker.js`\n- **Durable Object**：`OneBotHub`，管理 OneBot WebSocket、訊息佇列與回音防護\n- **D1**：Portal、設定、稽核、會話、通知路由與業務資料\n- **Vectorize**：經允許的長期語意記憶\n- **Workers AI**：Cloudflare AI binding\n- **外部模型**：Gemini／Gemma 為主要免費優先路由；DeepSeek 僅依既有成本與緊急後備規則使用\n- **Portal**：`https://qqai.ray2025.com/`\n- **Gemini Live**：`https://qqai.ray2025.com/live`\n\n專案沒有第二個 AI Worker。`src/` 的模組會由 Wrangler 打包進同一個 Worker。\n\n## 目前主要功能\n\n### AI 與對話\n\n- 群聊、私聊與同號人工控制\n- 引用、@ 關係、圖片、語音、影片、檔案與合併轉發解析\n- 長回答分段、回答截斷防護、短回覆去重\n- 需要搜尋時必須真正執行搜尋，不允許只說「等等去查」\n- 政治相關普通聊天在模型呼叫前靜默略過\n- 群組人格為持續基底，個人風格與模仿僅作覆蓋層\n- 群組人格最多保存 12,000 字元\n\n### 群規與安全\n\n- 群規持續監控與人工 `!检查`\n- 智慧嚴格度與誤判回饋\n- 多動作群規與累進處理\n- 種族歧視採固定公開警告，不自動撤回、禁言、踢出或累計處罰\n- 政治內容不進入群規分類或處罰\n- 高風險群操作使用待確認提案\n- `message`／`message_sent` 重複上報與機器人自我回覆循環防護\n\n### Portal\n\n- QQ 驗證碼登入、密碼登入與驗證碼重設密碼\n- 群組、成員、會話、AI 回覆、違規、通知、排程與系統維護頁面\n- 人工通知路由預設只找開發者\n- 對話與 AI 回覆採分頁載入，每頁最多 100 筆\n- 手機響應式版面與權限分層\n\n### 群務與協作\n\n- 活動建立、報名、候補、取消與通知\n- 投票\n- 排程與提醒\n- 申訴、建議、Bug／品質回報\n- 群管理操作提案\n- 狼人殺遊戲與 Portal 控制\n\n### 不消耗模型 API 的娛樂指令\n\n- `!骰子 [數量]d[面數]`\n- `!随机数 [最小值] [最大值]`\n- `!硬币`\n- `!猜拳 石头／剪刀／布`\n- `!选择 选项A | 选项B`\n- `!今日运势`\n- `!真心话`\n- `!大冒险`\n\n完整而且依權限篩選的指令清單請在 QQ 使用 `!help`。README 不再複製所有內部管理指令，以避免文件與實作再次分岔。\n\n## 同號操作\n\n使用機器人自己的 QQ 帳號人工操作時：\n\n- 一般聊天：`//內容`、`??內容` 或 `/!內容`\n- 指令：直接使用 `!指令`\n- 普通未加前綴的自身訊息不會觸發 AI\n- 機器人 API 發出的回覆會以 message ID 與 outbound fingerprint 阻擋，避免自我回覆循環\n\n群友使用 `/!內容` 時，該訊息完全不進入聊天、群規或插話 AI。\n\n## 失敗提示\n\n公開錯誤只顯示簡短的問題類型與建議重試時間，例如：\n\n```text\n目前API均无法调用，请过1分钟再试。\n```\n\n詳細 provider、HTTP 狀態、failure ID 與原始錯誤只保留在 Portal／稽核紀錄，不公開丟到群聊。\n\n## 安裝與驗證\n\n需求：\n\n- Node.js 22\n- npm\n- Wrangler 4.112.0\n\n```bash\nnpm install --ignore-scripts\nnpm run check\nnpm run check:bundle\n```\n\n`npm run check` 會依序執行永久 regression；`npm run check:bundle` 會執行 Wrangler dry-run，確認單一 Worker bundle 可建立。\n\n## Cloudflare 設定\n\n目前 `wrangler.toml` 主要 binding：\n\n```toml\nname = \"qqai\"\nmain = \"worker.js\"\ncompatibility_date = \"2026-07-21\"\ncompatibility_flags = [\"nodejs_compat\"]\n\n[ai]\nbinding = \"AI\"\n\n[[durable_objects.bindings]]\nname = \"ONEBOT_HUB\"\nclass_name = \"OneBotHub\"\n\n[[d1_databases]]\nbinding = \"DB\"\ndatabase_name = \"qqaibot\"\n\n[[vectorize]]\nbinding = \"VECTORIZE\"\nindex_name = \"qqai\"\n\n[triggers]\ncrons = [\"* * * * *\"]\n```\n\nDurable Object migration 歷史不可刪除或重新排序。\n\n## 常用 Secrets／環境變數\n\n依實際使用功能設定：\n\n- `ONEBOT_ACCESS_TOKEN`\n- `GEMINI_API_KEYS`\n- `VECTORIZE_GEMINI_KEYS`\n- `GEMINI_VISION_API_KEYS`\n- `DEEPSEEK_API_KEYS`\n- Portal 驗證與加密相關 Secrets\n- 可選的 Cloudflare Builds 查詢 Token\n\n不要把 API Key、Token、Cookie 或私鑰提交到 GitHub。\n\n## 部署\n\n```bash\nnpx wrangler login\nnpm run check\nnpm run check:bundle\nnpm run deploy\n```\n\n部署後至少進行：\n\n- OneBot WebSocket 連線\n- 同號 `!help` 與一般群友 `!help`\n- 一個娛樂指令\n- Portal 登入與通知路由讀寫\n- 政治靜默、種族歧視警告\n- 群組人格實際回答\n- API 全部不可用時的短錯誤提示\n\n## GitHub Actions\n\n`.github/workflows/validate.yml` 使用唯讀 `contents: read` 權限，在 `main` push 與 PR 對 `main` 時執行：\n\n1. 安裝依賴\n2. `npm run check`\n3. `npm run check:bundle`\n\n正式 workflow 不應包含候選程式產生器、診斷寫回或 `contents: write`。\n\n## 授權與責任\n\n本專案使用倉庫內既有的自訂限制性授權。使用、修改、部署與散布前，請先閱讀實際授權條款。軟體按現狀提供，不保證適用於任何特定用途。\n");
write("verify-entertainment-help-readme-errors.mjs", "import assert from \"node:assert/strict\";\nimport fs from \"node:fs\";\nimport {\n  handleEntertainmentCommand,\n  parseDice,\n  parseRandomRange,\n  splitChoices\n} from \"./src/games/entertainment.js\";\nimport { buildCommandHelp } from \"./src/help/commands.js\";\nimport {\n  classifyOperationalFailure,\n  formatRetryDelay,\n  parseRetryAfterSeconds\n} from \"./src/config/runtime.js\";\n\nconst fixedZero = () => 0;\nconst fixedHigh = () => 0.999999;\n\nassert.deepEqual(parseDice(\"骰子 3d20\"), { count: 3, sides: 20 });\nassert.equal(Boolean(parseDice(\"骰子 21d6\")?.error), true);\nassert.deepEqual(parseRandomRange(\"随机数 5 10\"), { min: 5, max: 10 });\nassert.deepEqual(splitChoices(\"火锅 | 烧烤，寿司\"), [\"火锅\", \"烧烤\", \"寿司\"]);\n\nassert.equal(handleEntertainmentCommand({ text: \"!骰子\", random: fixedZero }).text, \"骰子结果：1\");\nassert.match(handleEntertainmentCommand({ text: \"!骰子 3d6\", random: fixedHigh }).text, /6、6、6[\\s\\S]*18/);\nassert.equal(handleEntertainmentCommand({ text: \"!硬币\", random: fixedZero }).text, \"硬币结果：正面\");\nassert.match(handleEntertainmentCommand({ text: \"!猜拳 石头\", random: fixedZero }).text, /平局/);\nassert.equal(handleEntertainmentCommand({ text: \"!选择 A | B\", random: fixedHigh }).text, \"我选：B\");\nassert.equal(handleEntertainmentCommand({ text: \"!真心话\", random: fixedZero }).handled, true);\nassert.equal(handleEntertainmentCommand({ text: \"!大冒险\", random: fixedZero }).handled, true);\n\nconst fortuneA = handleEntertainmentCommand({\n  text: \"!今日运势\",\n  userId: \"10001\",\n  groupId: \"20001\",\n  now: Date.parse(\"2026-07-28T00:00:00+08:00\")\n});\nconst fortuneB = handleEntertainmentCommand({\n  text: \"!今日运势\",\n  userId: \"10001\",\n  groupId: \"20001\",\n  now: Date.parse(\"2026-07-28T20:00:00+08:00\")\n});\nassert.equal(fortuneA.text, fortuneB.text);\n\nconst memberHelp = buildCommandHelp({ role: \"member\" });\nassert.match(memberHelp, /【娱乐小游戏（不消耗模型 API）】/);\nassert.match(memberHelp, /• `!骰子/);\nassert.match(memberHelp, /• `!大冒险`/);\nassert.doesNotMatch(memberHelp, /【开发者专属】/);\nassert.doesNotMatch(memberHelp, /`!授权/);\n\nconst adminHelp = buildCommandHelp({ role: \"admin\", aiAdmin: true, groupOps: true });\nassert.match(adminHelp, /【AI 管理】/);\nassert.match(adminHelp, /【群操作】/);\n\nconst developerHelp = buildCommandHelp({ role: \"owner\", isDeveloper: true, aiAdmin: true, groupOps: true });\nassert.match(developerHelp, /【开发者专属】/);\nassert.match(developerHelp, /`!授权/);\n\nassert.equal(formatRetryDelay(30), \"30秒\");\nassert.equal(formatRetryDelay(61), \"2分钟\");\nassert.equal(formatRetryDelay(3700), \"2小时\");\nassert.equal(formatRetryDelay(90000), \"2天\");\nassert.equal(parseRetryAfterSeconds(\"retry-after: 45\"), 45);\nassert.equal(parseRetryAfterSeconds(\"retry_after=120\"), 120);\n\nconst noReply = classifyOperationalFailure(\"\", { disposition: \"worker_no_reply\" });\nassert.equal(noReply.userText, \"目前API均无法调用，请过1分钟再试。\");\nassert.doesNotMatch(noReply.userText, /Portal|系统维护|诊断/);\n\nconst limited = classifyOperationalFailure(\"rate limit retry-after: 45\", { status: 429 });\nassert.equal(limited.userText, \"模型请求过多，请过45秒再试。\");\nassert.doesNotMatch(limited.userText, /Portal|诊断编号/);\n\nconst worker = fs.readFileSync(\"worker.js\", \"utf8\");\nconst readme = fs.readFileSync(\"README.md\", \"utf8\");\nconst pkg = JSON.parse(fs.readFileSync(\"package.json\", \"utf8\"));\nassert.match(worker, /handleEntertainmentCommand/);\nassert.match(worker, /buildCommandHelp/);\nassert.doesNotMatch(worker, /let helpMsg = `🤖 QQAI 机器人指令清单/);\nassert.match(readme, /目前版本：\\*\\*2\\.7\\.11\\*\\*/);\nassert.match(readme, /OneBotHub/);\nassert.match(readme, /每頁最多 100 筆|每页最多 100 笔/);\nassert.doesNotMatch(readme, /!画图/);\nassert.doesNotMatch(readme, /短期上下文快取.*6 條/);\nassert.doesNotMatch(readme, /快捷登入 API 預留/);\nassert.equal(pkg.version, \"2.7.11\");\nassert.match(pkg.scripts.check, /verify-entertainment-help-readme-errors\\.mjs/);\n\nconsole.log(\"verify-entertainment-help-readme-errors: ok\");\n");
write("release-notes.json", "{\n  \"version\": \"2.7.11\",\n  \"notificationPolicy\": \"developer-only-by-default-with-explicit-opt-in\",\n  \"verification\": \"full-regression-and-single-worker-bundle\",\n  \"added\": [\n    \"新增八项不消耗模型API的娱乐指令：骰子、随机数、硬币、猜拳、选择、今日运势、真心话和大冒险\",\n    \"新增集中式、按权限显示的条列式指令帮助模块\",\n    \"新增秒、分钟、小时、天的人性化重试时间格式\"\n  ],\n  \"fixed\": [\n    \"重写README以反映当前单Worker、Durable Object、D1、Vectorize、Portal、群规和人格架构\",\n    \"修复!help长段落难以阅读、指令遗漏和普通成员看到不必要管理信息的问题\",\n    \"修复无回复错误向群友暴露Portal维护与诊断信息的问题\",\n    \"将API、限流、超时、资料库和OneBot故障改成简短且可执行的公开提示\"\n  ]\n}\n");

let worker = fs.readFileSync("worker.js", "utf8");
if (!worker.includes('from "./src/games/entertainment.js"')) {
  worker = replaceOnce(
    worker,
    'import { handleWerewolfOneBotEvent, injectWerewolfPortalClient, processWerewolfTimers } from "./src/games/werewolf.js";',
    'import { handleEntertainmentCommand } from "./src/games/entertainment.js";\nimport { handleWerewolfOneBotEvent, injectWerewolfPortalClient, processWerewolfTimers } from "./src/games/werewolf.js";',
    "entertainment import"
  );
}
if (!worker.includes('from "./src/help/commands.js"')) {
  worker = replaceOnce(
    worker,
    'import { buildHealthState } from "./src/health/runtime.js";',
    'import { buildHealthState } from "./src/health/runtime.js";\nimport { buildCommandHelp } from "./src/help/commands.js";',
    "help import"
  );
}
if (!worker.includes("const entertainmentResult = handleEntertainmentCommand")) {
  worker = replaceOnce(
    worker,
    "      const isOnlyMe = isDeveloper;\n",
    `      const isOnlyMe = isDeveloper;\n\n      const entertainmentResult = handleEntertainmentCommand({\n        text: cleanMessage,\n        userId,\n        groupId: currentGroupId,\n        now: Date.now()\n      });\n      if (entertainmentResult.handled) {\n        return jsonReply(\`${atSender}${entertainmentResult.text}\`);\n      }\n`,
    "entertainment route"
  );
}
if (!worker.includes("const helpMsg = buildCommandHelp")) {
  const helpStart = worker.indexOf("      // ==========================================\n      // 📜 基础系统帮助与状态模组");
  const helpEnd = worker.indexOf("      if (['!status'", helpStart);
  must(helpStart >= 0 && helpEnd > helpStart, "Missing inline help block");
  const replacement = `      // ==========================================\n      // 📜 权限感知条列式帮助\n      // ==========================================\n      if (['!help', '!帮助', '!幫助', '！help', '！帮助', '！幫助'].includes(msgLower)) {\n        const helpMsg = buildCommandHelp({\n          role: senderRole,\n          isDeveloper,\n          aiAdmin: permissionSet.aiAdmin,\n          groupOps: permissionSet.groupOps\n        });\n        return jsonReply(\`${atSender}${helpMsg}\`);\n      }\n\n`;
  worker = worker.slice(0, helpStart) + replacement + worker.slice(helpEnd);
}
fs.writeFileSync("worker.js", worker, "utf8");

let config = fs.readFileSync("src/config/runtime.js", "utf8");
config = config.replace('const VERSION = "2.7.10";', 'const VERSION = "2.7.11";');
const failureStart = config.indexOf("const EXPLICIT_REPLY_FAILURE_MESSAGES = Object.freeze({");
const affinityStart = config.indexOf("const AFFINITY_DEFAULTS", failureStart);
must(failureStart >= 0 && affinityStart > failureStart, "Missing operational failure block");
config = config.slice(0, failureStart) + "const EXPLICIT_REPLY_FAILURE_MESSAGES = Object.freeze({\n  worker_error: \"内部处理失败，请过1分钟再试。\",\n  worker_http_error: \"内部服务异常，请过1分钟再试。\",\n  worker_timeout: \"处理超时，请过30秒再试。\",\n  worker_empty_reply: \"模型没有返回内容，请过30秒再试。\",\n  worker_no_reply: \"目前API均无法调用，请过1分钟再试。\",\n  send_failed: \"消息发送失败，请过30秒再试。\",\n  uncaught_error: \"系统处理失败，请过1分钟再试。\"\n});\n\nfunction formatRetryDelay(seconds) {\n  const value = Math.max(1, Math.ceil(Number(seconds) || 1));\n  if (value < 60) return `${value}秒`;\n  if (value < 3600) return `${Math.ceil(value / 60)}分钟`;\n  if (value < 86400) return `${Math.ceil(value / 3600)}小时`;\n  return `${Math.ceil(value / 86400)}天`;\n}\n\nfunction parseRetryAfterSeconds(value) {\n  const source = String(value || \"\").normalize(\"NFKC\");\n  const match = source.match(/(?:retry[-_ ]?after|retry[-_ ]?delay|重试(?:等待|间隔|时间)?|請過|请过)\\s*[:=]?\\s*(\\d{1,7})\\s*(秒|分钟|分鐘|小时|小時|天|s|sec(?:ond)?s?|m|min(?:ute)?s?|h|hr|hours?|d|days?)?/i);\n  if (!match) return 0;\n  const amount = Math.max(1, Number(match[1]) || 0);\n  const unit = String(match[2] || \"秒\").toLowerCase();\n  let seconds = amount;\n  if (/^(?:分钟|分鐘|m|min)/i.test(unit)) seconds *= 60;\n  else if (/^(?:小时|小時|h|hr|hour)/i.test(unit)) seconds *= 3600;\n  else if (/^(?:天|d|day)/i.test(unit)) seconds *= 86400;\n  return Math.min(7 * 86400, Math.ceil(seconds));\n}\n\nfunction retryText(problem, seconds) {\n  return `${problem}，请过${formatRetryDelay(seconds)}再试。`;\n}\n\nfunction classifyOperationalFailure(errorLike, options = {}) {\n  const status = Number(options.status || 0);\n  const disposition = String(options.disposition || \"\");\n  const source = [\n    String(errorLike?.message || errorLike || \"\"),\n    String(options.preview || \"\"),\n    String(options.code || \"\"),\n    String(status || \"\")\n  ].join(\" \");\n  const lower = source.toLowerCase();\n  const retryAfter = parseRetryAfterSeconds(source);\n  let code = \"INTERNAL_EXECUTION_ERROR\";\n  let userText = EXPLICIT_REPLY_FAILURE_MESSAGES[disposition] || EXPLICIT_REPLY_FAILURE_MESSAGES.uncaught_error;\n  if (/api_keys?_missing|未配置.{0,20}(?:api|模型).{0,10}(?:key|金钥|密钥)|missing.{0,20}(?:api.?key|credential)/i.test(source)) {\n    code = \"MODEL_CREDENTIALS_MISSING\";\n    userText = \"目前没有可用的API密钥，请联系开发者。\";\n  } else if (status === 429 || /resource_exhausted|rate.?limit|too many requests|quota|额度不足|配额/i.test(source)) {\n    code = \"MODEL_RATE_LIMITED\";\n    userText = retryText(\"模型请求过多\", retryAfter || 60);\n  } else if (/abort|timeout|timed out|deadline|超时|超过时限/i.test(source) || disposition === \"worker_timeout\") {\n    code = \"PROCESSING_TIMEOUT\";\n    userText = retryText(\"处理超时\", retryAfter || 30);\n  } else if (/d1|database|sqlite|sql_|sql error|资料库|数据库|db_get|db_put/i.test(source)) {\n    code = \"DATABASE_ERROR\";\n    userText = retryText(\"资料库暂时不可用\", retryAfter || 60);\n  } else if (/napcat|onebot|websocket|no active websocket|rpc.*(?:fail|error)|send_(?:group|private)_msg/i.test(source) || disposition === \"send_failed\") {\n    code = \"NAPCAT_CONNECTION_ERROR\";\n    userText = retryText(\"消息连接异常\", retryAfter || 30);\n  } else if (/gemini|gemma|deepseek|workers.?ai|model|generatecontent/i.test(source)) {\n    code = \"MODEL_PROVIDER_ERROR\";\n    userText = retryText(\"目前API均无法调用\", retryAfter || 60);\n  } else if ([401, 403].includes(status) || /unauthorized|forbidden|鉴权|权限验证失败/i.test(source)) {\n    code = \"INTERNAL_AUTH_ERROR\";\n    userText = \"内部鉴权失败，请联系开发者。\";\n  } else if (disposition === \"worker_empty_reply\") {\n    code = \"EMPTY_MODEL_REPLY\";\n    userText = EXPLICIT_REPLY_FAILURE_MESSAGES.worker_empty_reply;\n  } else if ([502, 503, 504].includes(status)) {\n    code = \"UPSTREAM_UNAVAILABLE\";\n    userText = retryText(\"上游服务暂时不可用\", retryAfter || 60);\n  } else if (status >= 500) {\n    code = \"INTERNAL_HTTP_ERROR\";\n    userText = retryText(\"内部服务异常\", retryAfter || 60);\n  }\n  return { code, userText, raw: source.slice(0, 1000), lower };\n}\n\n\n" + config.slice(affinityStart);
config = config.replace(
  "VERSION, classifyOperationalFailure };",
  "VERSION, classifyOperationalFailure, formatRetryDelay, parseRetryAfterSeconds };"
);
must(config.includes("formatRetryDelay, parseRetryAfterSeconds"), "Failed to export retry helpers");
fs.writeFileSync("src/config/runtime.js", config, "utf8");

const packageJson = JSON.parse(fs.readFileSync("package.json", "utf8"));
packageJson.version = "2.7.11";
if (!String(packageJson.scripts.check || "").includes("verify-entertainment-help-readme-errors.mjs")) {
  packageJson.scripts.check = String(packageJson.scripts.check || "").trim() + " && node verify-entertainment-help-readme-errors.mjs";
}
fs.writeFileSync("package.json", JSON.stringify(packageJson, null, 2) + "\n", "utf8");

for (const file of fs.readdirSync(".")) {
  if (!/^verify-.*\.mjs$/.test(file)) continue;
  let content = fs.readFileSync(file, "utf8");
  if (content.includes("2.7.10")) {
    content = content.replaceAll("2.7.10", "2.7.11");
    fs.writeFileSync(file, content, "utf8");
  }
}

const finalWorker = fs.readFileSync("worker.js", "utf8");
must(finalWorker.includes("handleEntertainmentCommand"), "Worker entertainment integration missing");
must(finalWorker.includes("buildCommandHelp"), "Worker help integration missing");
must(!finalWorker.includes("let helpMsg = `🤖 QQAI 机器人指令清单"), "Legacy inline help remained");
must(JSON.parse(fs.readFileSync("package.json", "utf8")).version === "2.7.11", "Version update failed");
console.log("apply-v2.7.11: permanent patch written");
